/**
 * Re-entrancy flag for `project.cloned`.
 *
 * `cloneProject` applies search indexing, usage meters and the audit row
 * itself, then emits. Listeners for that event skip while the flag is set so
 * a process that has also registered the bus handlers does not apply them
 * twice. A bare `emit("project.cloned")` leaves the flag clear, and the
 * listeners perform the work.
 */

let depth = 0;

export function cloneEffectsInProgress(): boolean {
  return depth > 0;
}

export async function runCloneEffects(work: () => Promise<void>): Promise<void> {
  depth += 1;
  try {
    await work();
  } finally {
    depth -= 1;
  }
}

