/**
 * Copies a live project into a new one in the same workspace. The caller
 * chooses the name, slug and key; the slug is suffixed when it is taken and
 * the key is stored as given. Description, visibility, colour and lead come
 * from the source. The copy starts active, with no dates.
 *
 * When issues are included, every live issue is copied in number order and
 * renumbered from 1. Status, assignee, author and progress timestamps are
 * reset. Comments, attachments and links are not copied. Archived issues are
 * not copied. The source project and its issues are left untouched.
 *
 * Refuses before writing anything when the project quota, or the per-project
 * issue quota for the whole batch, would be exceeded. Publishes
 * `project.cloned` only — not `project.created` or `issue.created` — and still
 * indexes the copy and moves the usage meters.
 */
export async function cloneProject(
  actor: Actor,
  input: CloneProjectInput,
): Promise<Project> {
  assertOrgScope(actor, input.orgId);

  const source = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", source.id, source);
  assertCan(actor, "project:read", projectResource(source));
  assertCan(actor, "project:create", orgResource(input.orgId));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  const used = await projectRepo.countProjects(input.orgId);
  if (wouldExceedLimit(org.plan, "projects", used)) {
    throw new Error(
      `Plan ${org.plan} allows ${used} projects; upgrade to add another`,
    );
  }

  const includeIssues = input.includeIssues !== false;
  const sources = includeIssues
    ? await issueRepo.listLiveIssuesByNumber(input.orgId, source.id)
    : [];

  if (
    sources.length > 0 &&
    wouldExceedLimit(org.plan, "issuesPerProject", 0, sources.length)
  ) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${input.key}`,
    );
  }

  const project = await projectRepo.insertProject({
    orgId: input.orgId,
    name: input.name,
    slug: input.slug,
    key: input.key,
    description: source.description,
    visibility: source.visibility,
    leadId: source.leadId,
    color: source.color,
    targetDate: null,
  });

  const status = defaultIssueStatus(org.settings.defaultIssueStatus);
  const copies: Issue[] = [];
  let number = 1;
  for (const sourceIssue of sources) {
    copies.push(
      await issueRepo.insertIssue(
        {
          orgId: input.orgId,
          projectId: project.id,
          title: sourceIssue.title,
          description: sourceIssue.description,
          status,
          priority: sourceIssue.priority,
          assigneeId: null,
          parentId: null,
          estimate: sourceIssue.estimate,
          dueAt: sourceIssue.dueAt,
          labelIds: [...sourceIssue.labelIds],
        },
        actor.userId,
        number,
      ),
    );
    number += 1;
  }

  const payload = {
    ...actorEnvelope(actor),
    projectId: project.id,
    sourceProjectId: source.id,
    issuesCopied: copies.length,
  };

  await runCloneEffects(async () => {
    await recordActivity(payload.orgId, "project.cloned", {
      actorId: payload.actorId,
      subjectKind: "project",
      subjectId: payload.projectId,
      projectId: payload.projectId,
      summary: `Cloned project ${payload.projectId} from ${payload.sourceProjectId}`,
      metadata: {
        sourceProjectId: payload.sourceProjectId,
        issuesCopied: payload.issuesCopied,
      },
    });
    await indexProject(payload.orgId, project);
    for (const issue of copies) {
      await indexIssue(payload.orgId, issue);
    }
    await usageRepo.incrementUsage(payload.orgId, {
      projectsUsed: 1,
      issuesUsed: payload.issuesCopied,
    });
    await emit("project.cloned", payload);
  });

  return project;
}

function defaultIssueStatus(stored: string): IssueStatus {
  const parsed = issueStatusSchema.safeParse(stored);
  return parsed.success ? parsed.data : "backlog";
}

