import { afterAll, beforeAll, describe, expect, it } from "vitest";
import { cloneProjectSchema } from "@/schemas/project";
import { activityFilterSchema } from "@/schemas/activity";
import { subscribe } from "@/lib/event-bus";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { registerActivityListeners } from "@/server/services/activity-service";
import * as issueService from "@/server/services/issue-service";
import * as projectService from "@/server/services/project-service";
import { registerSearchListeners, search } from "@/server/services/search-service";
import { registerUsageListeners } from "@/server/services/usage-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { CloneProjectInput } from "@/schemas/project";
import type { OrgId, ProjectId } from "@/types/common";
import type { Actor } from "@/types/member";

function cloneInput(
  orgId: OrgId,
  projectId: ProjectId,
  overrides: Partial<CloneProjectInput> = {},
): CloneProjectInput {
  return {
    orgId,
    projectId,
    name: overrides.name ?? "Clone Train",
    slug: overrides.slug ?? "clone-train",
    key: overrides.key ?? "CLN",
    includeIssues: overrides.includeIssues ?? true,
  };
}

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  registerActivityListeners();
  registerSearchListeners();
  registerUsageListeners();
});

afterAll(() => {
  cleanup();
});

describe("cloneProject", () => {
  it("parses the schema and defaults includeIssues", () => {
    const parsed = cloneProjectSchema.parse({
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      projectId: "01HZZZPPPPPPPPPPPPPPPPPPPP",
      name: "Website relaunch",
      slug: "website-relaunch",
      key: "WEB",
    });
    expect(parsed.includeIssues).toBe(true);
    expect(activityFilterSchema.safeParse({
      orgId: "01HZZZAAAAAAAAAAAAAAAAAAAA",
      action: ["project.cloned"],
      limit: 25,
